package com.npchealthtext;

import java.util.Map;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import net.runelite.api.Client;
import net.runelite.api.NPC;
import net.runelite.api.widgets.Widget;
import net.runelite.client.util.WildcardMatcher;

/**
 * Manages extraction, parsing, normalization, and health ratio correlation
 * for the top OSRS Boss HP bar widget (Widget ID 303).
 */
public class BossHealthManager
{
	// Regex pattern to extract current and max HP values formatted as "current / max"
	private static final Pattern HP_PATTERN = Pattern.compile("(\\d+)\\s*/\\s*(\\d+)");

	// Regex pattern to remove HTML tags and commas from widget text
	private static final Pattern CLEAN_TAGS_AND_COMMAS = Pattern.compile("<[^>]*>|,");

	// Regex pattern to strip parenthetical descriptors (e.g. "(Melee)") from NPC names
	private static final Pattern PARENTHESES_PATTERN = Pattern.compile("\\(.*?\\)");

	// Regex pattern to verify string contains letters (used to find boss names in widgets)
	private static final Pattern HAS_LETTERS_PATTERN = Pattern.compile(".*[a-zA-Z].*");

	/**
	 * Immutable container holding scraped Boss HP widget details.
	 */
	public static class BossHealthData
	{
		private final String bossName;
		private final int currentHp;
		private final int maxHp;

		public BossHealthData(String bossName, int currentHp, int maxHp)
		{
			this.bossName = bossName;
			this.currentHp = currentHp;
			this.maxHp = maxHp;
		}

		public String getBossName()
		{
			return bossName;
		}

		public int getCurrentHp()
		{
			return currentHp;
		}

		public int getMaxHp()
		{
			return maxHp;
		}
	}

	/**
	 * Scrapes top-of-screen OSRS Boss HP bar widget (Widget group 303)
	 * to extract active boss name, current HP, and max HP.
	 *
	 * @param client RuneLite Client instance
	 * @return BossHealthData object if widget is active and contains valid HP, null otherwise
	 */
	public BossHealthData getBossHealthFromWidget(Client client)
	{
		if (client == null)
		{
			return null;
		}

		try
		{
			String bossName = null;
			int[] hpValues = null;

			// Inspect child widgets under group 303 (Boss Health Bar container)
			Widget bossWidgetGroup = client.getWidget(303, 0);
			if (bossWidgetGroup != null)
			{
				Widget[] children = bossWidgetGroup.getChildren();
				if (children != null)
				{
					for (Widget child : children)
					{
						if (child == null || child.isHidden() || child.getText() == null)
						{
							continue;
						}

						// Clean HTML formatting tags and commas from widget text
						String cleanText = CLEAN_TAGS_AND_COMMAS.matcher(child.getText()).replaceAll("").trim();
						if (cleanText.isEmpty())
						{
							continue;
						}

						// Parse numerical HP values ("cur / max")
						int[] parsed = parseHpString(cleanText);
						if (parsed != null && hpValues == null)
						{
							hpValues = parsed;
						}
						// Extract boss title string containing letters
						else if (bossName == null && HAS_LETTERS_PATTERN.matcher(cleanText).matches())
						{
							bossName = cleanText;
						}
					}
				}
			}

			// Fallback: check individual child widget slots 1 through 25
			for (int childId = 1; childId <= 25; childId++)
			{
				Widget w = client.getWidget(303, childId);
				if (w != null && !w.isHidden() && w.getText() != null)
				{
					String cleanText = CLEAN_TAGS_AND_COMMAS.matcher(w.getText()).replaceAll("").trim();
					if (cleanText.isEmpty())
					{
						continue;
					}

					int[] parsed = parseHpString(cleanText);
					if (parsed != null && hpValues == null)
					{
						hpValues = parsed;
					}
					else if (bossName == null && HAS_LETTERS_PATTERN.matcher(cleanText).matches())
					{
						bossName = cleanText;
					}
				}
			}

			// If valid current and max HP values were parsed, return container
			if (hpValues != null && hpValues.length >= 2)
			{
				return new BossHealthData(bossName, hpValues[0], hpValues[1]);
			}
		}
		catch (Exception ignored)
		{
		}

		return null;
	}

	/**
	 * Parses a string containing "current / max" health numbers into an integer array [current, max].
	 */
	public int[] parseHpString(String text)
	{
		if (text == null || text.trim().isEmpty())
		{
			return null;
		}
		try
		{
			String cleanText = CLEAN_TAGS_AND_COMMAS.matcher(text).replaceAll("").trim();
			Matcher matcher = HP_PATTERN.matcher(cleanText);
			if (matcher.find())
			{
				int cur = Integer.parseInt(matcher.group(1));
				int max = Integer.parseInt(matcher.group(2));
				if (max > 0 && cur >= 0)
				{
					return new int[]{cur, max};
				}
			}
		}
		catch (Exception ignored)
		{
		}
		return null;
	}

	/**
	 * Strips parenthetical suffixes, dashes, and colons to extract base boss name.
	 * E.g., "Vanguard (Melee)" -> "vanguard", "Olm's Hand - Left" -> "olm's hand".
	 */
	public String getNormalizedBaseName(String name)
	{
		if (name == null)
		{
			return "";
		}
		String cleaned = PARENTHESES_PATTERN.matcher(name).replaceAll("").trim().toLowerCase();
		if (cleaned.contains("-"))
		{
			cleaned = cleaned.split("-")[0].trim();
		}
		if (cleaned.contains(":"))
		{
			cleaned = cleaned.split(":")[0].trim();
		}
		return cleaned;
	}

	/**
	 * Determines whether an in-game NPC name matches a Boss Bar widget name using exact matching,
	 * normalized base name comparison, prefix matching, or wildcard patterns.
	 */
	public boolean bossNameMatches(String npcName, String widgetBossName)
	{
		if (npcName == null || widgetBossName == null)
		{
			return false;
		}

		String cleanNpc = npcName.trim().toLowerCase();
		String cleanWidget = widgetBossName.trim().toLowerCase();

		if (cleanNpc.isEmpty() || cleanWidget.isEmpty())
		{
			return false;
		}

		// Direct exact match check
		if (cleanNpc.equals(cleanWidget))
		{
			return true;
		}

		// Normalized base name comparison (stripping suffixes/prefixes)
		String baseNpc = getNormalizedBaseName(npcName);
		String baseWidget = getNormalizedBaseName(widgetBossName);

		if (!baseNpc.isEmpty() && baseNpc.equals(baseWidget))
		{
			return true;
		}

		// Prefix matching for base names of length >= 4
		if (baseNpc.length() >= 4 && baseWidget.length() >= 4)
		{
			if (baseNpc.startsWith(baseWidget) || baseWidget.startsWith(baseNpc))
			{
				return true;
			}
		}

		// Wildcard pattern matching fallback
		return WildcardMatcher.matches(cleanWidget, cleanNpc) || WildcardMatcher.matches(cleanNpc, cleanWidget);
	}

	/**
	 * Counts active (non-dead) NPCs in the current room matching the specified boss widget name.
	 */
	public int countMatchingNpcs(Iterable<NPC> npcs, String bossName)
	{
		if (npcs == null || bossName == null || bossName.trim().isEmpty())
		{
			return 0;
		}
		int count = 0;
		for (NPC n : npcs)
		{
			if (n != null && !n.isDead() && n.getName() != null && bossNameMatches(n.getName(), bossName))
			{
				count++;
			}
		}
		return count;
	}

	/**
	 * Checks if an NPC's client health bar ratio (ratio / scale) matches the top Boss Bar widget ratio
	 * (currentHp / maxHp) within a quantization tolerance.
	 */
	public boolean isNpcRatioMatchingBossWidget(NPC npc, int ratio, int scale, BossHealthData bossWidgetData, Map<Integer, int[]> lastHpMap)
	{
		if (npc == null || bossWidgetData == null || bossWidgetData.getMaxHp() <= 0 || bossWidgetData.getCurrentHp() < 0)
		{
			return false;
		}

		// Fallback to cached health ratio if current NPC ratio/scale is invalid (-1)
		if (ratio < 0 || scale <= 0)
		{
			int index = npc.getIndex();
			if (lastHpMap != null && lastHpMap.containsKey(index))
			{
				int[] cached = lastHpMap.get(index);
				ratio = cached[0];
				scale = cached[1];
			}
		}

		if (ratio < 0 || scale <= 0)
		{
			return false;
		}

		// Calculate client health fraction and boss widget health fraction
		double npcFraction = (double) ratio / scale;
		double bossFraction = (double) bossWidgetData.getCurrentHp() / bossWidgetData.getMaxHp();

		// Calculate ratio quantization tolerance based on health scale
		double tolerance = (1.5 / scale) + 0.01;
		return Math.abs(npcFraction - bossFraction) <= tolerance;
	}
}

package com.npchealthtext;

public enum DisplayMode
{
	BOTH("Value/Max (%)"),
	BOTH_VALUE_ONLY("Value (%)"),
	BOTH_PERCENT_FIRST_VALUE("% (Value)"),
	BOTH_PERCENT_FIRST_HP_SUFFIX("% (Value HP)"),
	BOTH_PERCENT_FIRST_MAX("% (Value/Max)"),
	HP_VALUE("Value/Max"),
	HP_VALUE_ONLY("Value Only"),
	HP_PERCENTAGE("% Only"),
	CUSTOM("Custom");

	private final String displayName;

	DisplayMode(String displayName)
	{
		this.displayName = displayName;
	}

	@Override
	public String toString()
	{
		return displayName;
	}
}

package com.npchealthtext;

public enum FontType
{
	RUNESCAPE_BOLD("RuneScape Bold"),
	RUNESCAPE("RuneScape"),
	RUNESCAPE_SMALL("RuneScape Small"),
	ARIAL("Arial"),
	DIALOG("Dialog"),
	SANS_SERIF("Sans Serif"),
	SERIF("Serif"),
	MONOSPACED("Monospaced"),
	CUSTOM("Custom / System Font");

	private final String displayName;

	FontType(String displayName)
	{
		this.displayName = displayName;
	}

	@Override
	public String toString()
	{
		return displayName;
	}
}

package com.npchealthtext;

public enum NpcDisplayMode
{
	SHOW_TARGET_NPC("Show Target NPC"),
	SHOW_ALL("Show All"),
	SHOW_WHITELISTED("Show Whitelisted"),
	SHOW_WHITELIST_TARGET("Show Whitelist Target");

	private final String name;

	NpcDisplayMode(String name)
	{
		this.name = name;
	}

	@Override
	public String toString()
	{
		return name;
	}
}

package com.npchealthtext;

import net.runelite.api.NPC;
import net.runelite.client.util.WildcardMatcher;

/**
 * Handles target interaction detection, NPC display mode filtering (SHOW_TARGET_NPC,
 * SHOW_WHITELISTED, etc.), and wildcard matching against whitelists and blacklists.
 */
public class NpcFilterManager
{
	private final BossHealthManager bossHealthManager;

	public NpcFilterManager()
	{
		this(new BossHealthManager());
	}

	public NpcFilterManager(BossHealthManager bossHealthManager)
	{
		this.bossHealthManager = bossHealthManager != null ? bossHealthManager : new BossHealthManager();
	}

	/**
	 * Evaluates whether an NPC is considered an active target.
	 * Checks direct player interaction, recent combat history, and boss widget correlation.
	 *
	 * @param npc Target NPC to evaluate
	 * @param context Frame-level targeting state
	 * @return true if the NPC is an active target, false otherwise
	 */
	public boolean isTarget(NPC npc, TargetContext context)
	{
		if (npc == null || context == null || PetConstants.isPet(npc))
		{
			return false;
		}

		// Player is directly attacking / interacting with this NPC
		if (context.getCurrentInteracting() == npc)
		{
			return true;
		}

		// NPC is directly attacking / targeting the local player
		if (context.getLocalPlayer() != null && npc.getInteracting() == context.getLocalPlayer())
		{
			return true;
		}

		// NPC was recently targeted within the last 15 seconds (or active boss bar)
		if (context.getLastTargetNpc() == npc && !npc.isDead())
		{
			if (context.isBossBarActive() || System.currentTimeMillis() - context.getLastTargetTime() < 15000)
			{
				return true;
			}
		}

		// Active boss bar widget fallback for single boss or matching ratio NPC
		if (context.isBossBarActive() && !npc.isDead() && context.getLastTargetNpc() == null)
		{
			if (context.getMatchingBossCount() <= 1
				|| bossHealthManager.isNpcRatioMatchingBossWidget(
					npc,
					npc.getHealthRatio(),
					npc.getHealthScale(),
					context.getBossWidgetData(),
					context.getLastHpMap()))
			{
				return true;
			}
		}

		return false;
	}

	/**
	 * Determines whether an NPC overlay should be rendered based on NpcDisplayMode,
	 * target status, whitelist configuration, and blacklist configuration.
	 */
	public boolean shouldRenderForDisplayMode(String npcName, boolean isTarget, NpcDisplayMode mode, String nameList, String blacklist)
	{
		if (npcName == null || PetConstants.isPetName(npcName))
		{
			return false;
		}

		if (mode == null)
		{
			mode = NpcDisplayMode.SHOW_TARGET_NPC;
		}

		switch (mode)
		{
			case SHOW_TARGET_NPC:
				if (!isTarget)
				{
					return false;
				}
				break;
			case SHOW_WHITELISTED:
				if (!isNameInList(npcName, nameList))
				{
					return false;
				}
				break;
			case SHOW_WHITELIST_TARGET:
				if (!isTarget || !isNameInList(npcName, nameList))
				{
					return false;
				}
				break;
			case SHOW_ALL:
			default:
				break;
		}

		// Enforce blacklist filtering if blacklist is configured
		if (blacklist != null && !blacklist.trim().isEmpty())
		{
			if (isNameInList(npcName, blacklist))
			{
				return false;
			}
		}

		return true;
	}

	/**
	 * Checks if an NPC name matches any item in a comma-separated wildcard pattern list.
	 */
	public boolean isNameInList(String npcName, String rawList)
	{
		if (rawList == null || rawList.trim().isEmpty() || npcName == null)
		{
			return false;
		}

		String lowerName = npcName.trim().toLowerCase();
		String[] parts = rawList.split(",");
		for (String part : parts)
		{
			String pattern = part.trim().toLowerCase();
			if (!pattern.isEmpty() && WildcardMatcher.matches(pattern, lowerName))
			{
				return true;
			}
		}
		return false;
	}
}

package com.npchealthtext;

import java.awt.Color;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import net.runelite.client.ui.FontManager;

/**
 * Handles font resolution, snapped font sizing for RuneScape bitmap fonts,
 * text antialiasing hints, text styling (Outline, Shadow, Shadow Bold),
 * and pixel-nearest-neighbor font scaling.
 */
public class NpcFontRenderer
{
	/**
	 * Configures Graphics2D rendering hints based on whether the selected font is a RuneScape bitmap font.
	 */
	public void configureRenderingHints(Graphics2D graphics, FontType type)
	{
		boolean isRuneScape = isRuneScapeFont(type);

		if (isRuneScape)
		{
			graphics.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_OFF);
			graphics.setRenderingHint(RenderingHints.KEY_FRACTIONALMETRICS, RenderingHints.VALUE_FRACTIONALMETRICS_OFF);
		}
		else
		{
			graphics.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_ON);
			graphics.setRenderingHint(RenderingHints.KEY_FRACTIONALMETRICS, RenderingHints.VALUE_FRACTIONALMETRICS_ON);
		}
	}

	public boolean isRuneScapeFont(FontType type)
	{
		return type == FontType.RUNESCAPE
			|| type == FontType.RUNESCAPE_SMALL
			|| type == FontType.RUNESCAPE_BOLD;
	}

	/**
	 * Snaps configured font size to an integer multiple of the native RuneScape bitmap font size to prevent blurring.
	 */
	public int getSnappedFontSize(FontType type, int currentSize)
	{
		if (isRuneScapeFont(type))
		{
			Font nativeFont = getNativeRuneScapeFont(type);
			int nativeSize = nativeFont.getSize();
			int scale = Math.max(1, Math.round((float) currentSize / nativeSize));
			return nativeSize * scale;
		}
		return currentSize;
	}

	/**
	 * Resolves system or RuneLite Font instance matching configuration.
	 */
	public Font resolveFont(FontType type, int fontSize, String customFontName)
	{
		Font base;

		if (type == null)
		{
			type = FontType.RUNESCAPE_SMALL;
		}

		switch (type)
		{
			case RUNESCAPE:
				base = FontManager.getRunescapeFont();
				break;
			case RUNESCAPE_SMALL:
				base = FontManager.getRunescapeSmallFont();
				break;
			case RUNESCAPE_BOLD:
				base = FontManager.getRunescapeBoldFont();
				break;
			case ARIAL:
				base = new Font("Arial", Font.PLAIN, fontSize);
				break;
			case DIALOG:
				base = new Font(Font.DIALOG, Font.PLAIN, fontSize);
				break;
			case SANS_SERIF:
				base = new Font(Font.SANS_SERIF, Font.PLAIN, fontSize);
				break;
			case SERIF:
				base = new Font(Font.SERIF, Font.PLAIN, fontSize);
				break;
			case MONOSPACED:
				base = new Font(Font.MONOSPACED, Font.PLAIN, fontSize);
				break;
			case CUSTOM:
				base = new Font(customFontName != null ? customFontName : "Arial", Font.PLAIN, fontSize);
				break;
			default:
				base = FontManager.getRunescapeSmallFont();
				break;
		}
		return base.deriveFont((float) getSnappedFontSize(type, fontSize));
	}

	/**
	 * Draws styled text onto canvas with outline, shadow, or shadow bold effects.
	 */
	public void drawStyledString(Graphics2D graphics, String text, int x, int y, Color mainColor, TextStyle style, FontType fontType)
	{
		if (style == null)
		{
			style = TextStyle.SHADOW_BOLD;
		}

		int alpha = mainColor != null ? mainColor.getAlpha() : 255;
		Color shadowColorWithAlpha = new Color(0, 0, 0, alpha);

		// Render text outline
		if (style == TextStyle.OUTLINE || style == TextStyle.OUTLINE_SHADOW)
		{
			graphics.setColor(shadowColorWithAlpha);
			graphics.drawString(text, x - 1, y);
			graphics.drawString(text, x + 1, y);
			graphics.drawString(text, x, y - 1);
			graphics.drawString(text, x, y + 1);

			if (fontType != FontType.RUNESCAPE_SMALL)
			{
				graphics.drawString(text, x - 1, y - 1);
				graphics.drawString(text, x + 1, y - 1);
				graphics.drawString(text, x - 1, y + 1);
				graphics.drawString(text, x + 1, y + 1);
			}
		}

		// Render text shadow
		if (style == TextStyle.SHADOW || style == TextStyle.OUTLINE_SHADOW)
		{
			graphics.setColor(shadowColorWithAlpha);
			graphics.drawString(text, x + 1, y + 1);
		}
		else if (style == TextStyle.SHADOW_BOLD)
		{
			graphics.setColor(shadowColorWithAlpha);
			graphics.drawString(text, x + 1, y + 1);
			graphics.drawString(text, x + 1, y + 2);
			graphics.drawString(text, x + 2, y + 1);
			graphics.drawString(text, x + 2, y + 2);
		}

		// Draw foreground main text
		graphics.setColor(mainColor);
		graphics.drawString(text, x, y);
	}

	/**
	 * Draws text onto canvas. For scaled RuneScape bitmap fonts, renders to an off-screen BufferedImage
	 * and uses nearest-neighbor interpolation to prevent pixel distortion.
	 */
	public void drawText(Graphics2D graphics, String text, int x, int y, FontMetrics fm, Color textColor, FontType type, int fontSize, TextStyle style)
	{
		drawText(graphics, text, x, y, fm, textColor, type, fontSize, style, null, 0, 0.0);
	}

	/**
	 * Draws text onto canvas with optional damage pulse feathered glow aura effect.
	 */
	public void drawText(
		Graphics2D graphics,
		String text,
		int x,
		int y,
		FontMetrics fm,
		Color textColor,
		FontType type,
		int fontSize,
		TextStyle style,
		Color pulseColor,
		int pulseIntensity,
		double pulseFactor)
	{
		int maxRadius = (pulseColor != null && pulseIntensity > 0 && pulseFactor > 0.0)
			? Math.max(1, Math.round((pulseIntensity / 2.0f) * (float) pulseFactor))
			: 0;

		if (isRuneScapeFont(type))
		{
			Font nativeFont = getNativeRuneScapeFont(type);
			int nativeSize = nativeFont.getSize();
			int currentSize = getSnappedFontSize(type, fontSize);

			// Off-screen nearest-neighbor scaling for enlarged RuneScape fonts
			if (currentSize != nativeSize)
			{
				int scale = currentSize / nativeSize;
				FontMetrics nativeFm = graphics.getFontMetrics(nativeFont);
				int nativeW = nativeFm.stringWidth(text);
				int nativeH = nativeFm.getHeight();

				if (nativeW <= 0 || nativeH <= 0)
				{
					return;
				}

				int glowPad = 4 + maxRadius;
				BufferedImage img = new BufferedImage(
					nativeW + glowPad * 2, nativeH + glowPad * 2, BufferedImage.TYPE_INT_ARGB);
				Graphics2D g2d = img.createGraphics();
				g2d.setFont(nativeFont);
				g2d.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_OFF);
				g2d.setRenderingHint(RenderingHints.KEY_FRACTIONALMETRICS, RenderingHints.VALUE_FRACTIONALMETRICS_OFF);

				int fontAscent = nativeFm.getAscent();
				int textX = glowPad;
				int textY = fontAscent + glowPad;

				if (maxRadius > 0)
				{
					drawFeatheredGlow(g2d, text, textX, textY, pulseColor, pulseIntensity, pulseFactor);
				}

				drawStyledString(g2d, text, textX, textY, textColor, style, type);
				g2d.dispose();

				int scaledW = (nativeW + glowPad * 2) * scale;
				int scaledH = (nativeH + glowPad * 2) * scale;
				int topY = y - fontAscent * scale;
				int drawX = x - glowPad * scale;
				int drawY = topY - glowPad * scale;

				Object oldInterpolation = graphics.getRenderingHint(RenderingHints.KEY_INTERPOLATION);
				graphics.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_NEAREST_NEIGHBOR);
				graphics.drawImage(img, drawX, drawY, scaledW, scaledH, null);
				if (oldInterpolation != null)
				{
					graphics.setRenderingHint(RenderingHints.KEY_INTERPOLATION, oldInterpolation);
				}
				return;
			}
		}

		if (maxRadius > 0)
		{
			drawFeatheredGlow(graphics, text, x, y, pulseColor, pulseIntensity, pulseFactor);
		}

		drawStyledString(graphics, text, x, y, textColor, style, type);
	}

	/**
	 * Renders concentric translucent feathered glow halo around text.
	 */
	public void drawFeatheredGlow(Graphics2D graphics, String text, int x, int y, Color pulseColor, int pulseIntensity, double pulseFactor)
	{
		if (pulseColor == null || pulseIntensity <= 0 || pulseFactor <= 0.0)
		{
			return;
		}

		int maxRadius = Math.max(1, Math.round((pulseIntensity / 2.0f) * (float) pulseFactor));
		int baseAlpha = pulseColor.getAlpha();
		int r = pulseColor.getRed();
		int g = pulseColor.getGreen();
		int b = pulseColor.getBlue();

		for (int radius = maxRadius; radius >= 1; radius--)
		{
			double layerFactor = 1.0 - ((double) (radius - 1) / maxRadius);
			int layerAlpha = (int) Math.round(baseAlpha * pulseFactor * layerFactor * 0.35);
			if (layerAlpha <= 0)
			{
				continue;
			}

			graphics.setColor(new Color(r, g, b, Math.min(255, layerAlpha)));
			for (int dx = -radius; dx <= radius; dx++)
			{
				for (int dy = -radius; dy <= radius; dy++)
				{
					if (dx * dx + dy * dy <= radius * radius + 1)
					{
						graphics.drawString(text, x + dx, y + dy);
					}
				}
			}
		}
	}

	private Font getNativeRuneScapeFont(FontType type)
	{
		if (type == null)
		{
			return FontManager.getRunescapeSmallFont();
		}
		switch (type)
		{
			case RUNESCAPE:
				return FontManager.getRunescapeFont();
			case RUNESCAPE_SMALL:
				return FontManager.getRunescapeSmallFont();
			case RUNESCAPE_BOLD:
			default:
				return FontManager.getRunescapeBoldFont();
		}
	}
}

