/**
 * Registry of pet names in OSRS
 * Used to filter out pet NPCs so HP overlays do not appear for pets
 * and pets do not interfere with target tracking.
 */
public class PetConstants
{
	/**
	 * Set of normalized (lowercase) pet names in OSRS.
	 * Update this list as new pets or pet metamorphoses are added to the game.
	 */
	public static final Set<String> PET_NAMES;

	static
	{
		Set<String> names = new HashSet<>();

		// Boss Pets
		names.add("abyssal orphan");
		names.add("aggy");
		names.add("baby mole");
		names.add("baron");
		names.add("bran");
		names.add("beef");
		names.add("butch");
		names.add("callisto cub");
		names.add("artio cub");
		names.add("dom");
		names.add("gull");
		names.add("hellpuppy");
		names.add("huberte");
		names.add("ikkle hydra");
		names.add("jal-nib-rek");
		names.add("jal-rek-jad");
		names.add("tzrek-zuk");
		names.add("kalphite princess");
		names.add("lil' zik");
		names.add("lil'viathan");
		names.add("little nightmare");
		names.add("little parasite");
		names.add("maggot marquess");
		names.add("moxi");
		names.add("muphin");
		names.add("nexling");
		names.add("nid");
		names.add("noon");
